class Ignore:
    def __init__(self, *types):
        self.types = types

    def __enter__(self):
        return self

    def __exit__(self, exc_type, exc, tb):
        # True only for the listed types; None, False otherwise
        return exc_type is not None and issubclass(exc_type, self.types)

with Ignore(KeyError):
    {}['missing']
print('still running')

from contextlib import contextmanager

@contextmanager
def acquired(lock_log, name):
    lock_log.append(f'acquire {name}')
    try:
        yield name
    finally:
        lock_log.append(f'release {name}')   # runs on error too

log = []
try:
    with acquired(log, 'db'):
        raise TimeoutError
except TimeoutError:
    pass
print(log)   # ['acquire db', 'release db']

from contextlib import suppress, nullcontext, closing

config = {}
with suppress(KeyError):
    del config['cache']        # fine if it was never there

def process(items, lock=None):
    with lock if lock is not None else nullcontext():
        return sorted(items)

class Conn:
    def close(self):
        print('closed')

with closing(Conn()) as conn:
    pass                       # prints closed

