from contextlib import contextmanager

@contextmanager
def transaction(store):
    snapshot = dict(store)
    try:
        yield store
    except Exception:
        store.clear()
        store.update(snapshot)   # roll back
        raise                    # let the caller see the failure

accounts = {'alice': 50, 'bob': 0}
try:
    with transaction(accounts):
        accounts['alice'] -= 80
        if accounts['alice'] < 0:
            raise ValueError('insufficient funds')
        accounts['bob'] += 80
except ValueError as err:
    print(err)
print(accounts)   # {'alice': 50, 'bob': 0}

