from contextlib import contextmanager


@contextmanager
def transaction(store, log):
    snapshot = dict(store)
    try:
        yield store
    except Exception as err:
        store.clear()
        store.update(snapshot)
        log.append(f'rollback {type(err).__name__}')
        raise
    else:
        log.append('commit')


def apply_op(store, op):
    kind = op[0]
    if kind == 'set':
        store[op[1]] = op[2]
    elif kind == 'add':
        store[op[1]] = store[op[1]] + op[2]
    elif kind == 'del':
        del store[op[1]]
    else:
        raise ValueError(f'unknown op {kind!r}')


def apply_batches(store, batches):
    store = dict(store)
    log = []
    for batch in batches:
        try:
            with transaction(store, log):
                for op in batch:
                    apply_op(store, op)
        except (KeyError, TypeError, ValueError):
            pass
    return {'store': store, 'log': log}

The transaction is a `@contextmanager` with `try`/`except`/`else` around `yield`: the snapshot is taken on entry, `else` logs the commit only when the body finished cleanly, and `except` restores the snapshot in place (callers holding the same dict see the rollback) before re-raising. Re-raising keeps the manager honest: it undoes its own work but does not decide that a failure is acceptable; the caller does, by catching only the three expected error types. Each batch costs O(k) for the snapshot where k is the store size, plus O(m) for its m operations. `dict(store)` is a shallow copy, which is enough here because values are replaced, never mutated in place.

