from contextlib import ExitStack


class Resource:
    def __init__(self, name, log):
        self.name = name
        self.log = log

    def __enter__(self):
        self.log.append(f'open {self.name}')
        return self

    def __exit__(self, exc_type, exc, tb):
        self.log.append(f'close {self.name}')
        return False


def cleanup_order(names, fail_at):
    log = []
    try:
        with ExitStack() as stack:
            for name in names:
                if name == fail_at:
                    raise RuntimeError(name)
                stack.enter_context(Resource(name, log))
            log.append('work')
    except RuntimeError as err:
        log.append(f'failed {err}')
    return log

class Session:
    def __init__(self, log):
        self.log = log
        self.depth = 0

    def __enter__(self):
        self.depth += 1
        if self.depth == 1:
            self.log.append('connect')
        return self

    def __exit__(self, exc_type, exc, tb):
        self.depth -= 1
        if self.depth == 0:
            self.log.append('rollback' if exc_type else 'commit')
            self.log.append('disconnect')
        return False


def _run(session, block):
    for item in block:
        if isinstance(item, list):
            with session:
                _run(session, item)
        elif item == 'boom':
            raise ValueError(item)
        else:
            session.log.append(f'{item}@{session.depth}')


def session_log(script):
    log = []
    session = Session(log)
    try:
        with session:
            _run(session, script)
    except ValueError:
        log.append('error')
    return log

